import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
/* eslint-disable */
import { genrate_visit_management_reports } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_visittype_master } from "@/mixins/GetVisitMaster";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
const FileSaver = require("file-saver");
import axios from "axios";
export default {
  mixins: [get_visittype_master, get_all_org_users],
  props: {
    logexport: Boolean
  },
  data() {
    return {
      loading: false,
      monthPicker: false,
      visitArray: [],
      visitlist: [],
      userselect: "",
      userArray: [],
      searchvisit: "",
      visitselect: "",
      datedisplay: "",
      datedisplayMonth: "",
      yearfilter: new Date().getFullYear(),
      monthfilter: "",
      monthNames: ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"],
      itemyears: [],
      date: new Date().toISOString().substr(0, 7)
    };
  },
  watch: {
    logexport: {
      async handler() {
        if (this.logexport == true) {
          this.date = new Date().toISOString().substr(0, 7);
          await Promise.all([this.get_visittype_master(), this.get_all_org_users()]);
          await this.fetch_details();
          this.populateYearItems();
          this.setInitialFilters();
        }
      },
      immediate: true
    }
  },
  async mounted() {
    this.get_visittype_master();
  },
  methods: {
    get_data(val) {},
    filterVisits() {
      this.visitArray = this.visitlist;
    },
    fetch_details() {
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE") {
          this.userArray.push({
            full_user_name: element.full_user_name,
            user_id: element.user_email_id
          });
        }
        this.userArray.unshift({
          full_user_name: "All",
          user_id: "ALL"
        });
      });
      this.Mastervisit.forEach(element => {
        this.visitlist.push({
          visit_type_name: element.workflow_name + " V " + element.workflow_version,
          visit_type_id: element.workflow_id,
          created_on: this.get_date(element.workflow_created_on).split(",")[0]
        });
      });
      this.filterVisits();
    },
    get_date(date) {
      let a = new Date(date * 1000).toLocaleTimeString("en-In", {
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit"
      });
      return a.toUpperCase();
    },
    close_dialog() {
      this.date = new Date().toISOString().substr(0, 7);
      this.visitselect = "";
      this.monthPicker = false;
      this.$emit("clicked", 0);
    },
    async download_invoice(url) {
      var fileName = url.split("/").pop();
      axios({
        url: url,
        method: "GET",
        responseType: "blob"
      }).then(response => {
        const blob = new Blob([response.data], {
          type: response.headers["content-type"]
        });
        FileSaver.saveAs(blob, fileName);
      }).catch(error => {
        console.error("Error downloading the file:", error);
      });
    },
    async export_mutation() {
      if (this.$refs.form.validate()) {
        this.loading = true;
        var data = this.$store.getters.GetUserObj;
        try {
          let result = await API.graphql(graphqlOperation(genrate_visit_management_reports, {
            input: {
              user_email_id: this.userselect,
              workflow_id: this.visitselect,
              month_year: this.date
            }
          }));
          this.loading = false;
          var response = JSON.parse(result.data.genrate_visit_management_reports);
          this.loading = false;
          if (response.Status == "SUCCESS") {
            this.$emit("successMsg", response.Message);
            this.download_invoice(response.data);
            this.$emit("exportupdate", 0);
          } else {
            this.$emit("errorMsg", response.Message);
          }
        } catch (error) {
          this.loading = false;
          this.$emit("errorMsg", error.errors[0].message);
        }
      }
    },
    populateYearItems() {
      const currentYear = new Date().getFullYear();
      this.itemyears = Array.from({
        length: 10
      }, (_, index) => currentYear - index);
    },
    setInitialFilters() {
      const currentYear = new Date().getFullYear();
      this.yearfilter = currentYear;
      this.monthfilter = this.monthNames[new Date().getMonth()] || "Jan";
      this.updateDatedisplayMonth();
      this.datedisplay = this.datedisplayMonth || `${this.monthfilter} ${this.yearfilter}`;
    },
    updateDatedisplayMonth() {
      if (this.yearfilter && this.monthfilter) {
        this.datedisplayMonth = `${this.monthfilter} ${this.yearfilter}`;
      } else {
        const currentDate = new Date();
        this.datedisplayMonth = `${this.monthNames[currentDate.getMonth()]} ${currentDate.getFullYear()}`;
      }
    },
    selectMonth(month) {
      this.monthfilter = month;
    },
    saveSelection() {
      this.datedisplay = `${this.monthfilter} ${this.yearfilter}`;
      this.date = `${this.yearfilter}-${this.monthNames.indexOf(this.monthfilter) + 1}`.padStart(2, "0");
      this.monthPicker = false;
      this.get_data(this.date);
    },
    isMonthDisabled(index) {
      const currentYear = new Date().getFullYear();
      const currentMonth = new Date().getMonth();
      if (this.yearfilter === currentYear && index > currentMonth) {
        return true;
      }
      return false;
    }
  }
};
